248	     9	
249	    10	/**
250	    11	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
251	    12	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
252	    13	 * (half-even) at every step.
253	    14	 */
254	    15	public final class PriceCalculator {
255	    16	
256	    17	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
257	    18	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
258	    19	    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
259	    20	    static final Map<String, BigDecimal> COMPANY_DISCOUNTS = Map.of(
260	    21	            "TECNOSUL", new BigDecimal("0.12"),
261	    22	            "AGROVALE", new BigDecimal("0.18"),
262	    23	            "FARMAVIDA", new BigDecimal("0.25"));
263	    24	
264	    25	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
265	    26	        int nights = 0;
266	    27	        BigDecimal subtotal = cents(BigDecimal.ZERO);
267	    28	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
268	    29	            subtotal = subtotal.add(nightPrice(room, night));
269	    30	            nights++;
270	    31	        }
271	    32	        if (ratePlan == RatePlan.WEEKEND_PACKAGE) {
272	    33	            BigDecimal packagePrice = switch (room.type()) {
273	    34	                case STANDARD -> new BigDecimal("520.00");
274	    35	                case DELUXE -> new BigDecimal("820.00");
275	    36	                case SUITE -> new BigDecimal("1200.00");
276	    37	            };
277	    38	            return new Price(nights, packagePrice, cents(BigDecimal.ZERO), packagePrice);
278	    39	        }
279	    40	        BigDecimal discount = switch (ratePlan) {
280	    41	            case STANDARD -> cents(BigDecimal.ZERO);
281	    42	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
282	    43	            case CORPORATE -> cents(subtotal.multiply(COMPANY_DISCOUNTS.get(companyCode)));
283	    44	            case LONG_STAY -> cents(subtotal.multiply(LONG_STAY_DISCOUNT));
284	    45	            case WEEKEND_PACKAGE -> cents(BigDecimal.ZERO);
285	    46	        };
286	    47	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
287	    48	    }
288	    49	
289	    50	    BigDecimal nightPrice(Room room, LocalDate night) {
290	    51	        BigDecimal nightlyRate = room.nightlyRate();
291	    52	        if (isHighSeason(night)) {
292	    53	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
293	    54	        }
294	    55	        return cents(nightlyRate);
295	    56	    }
296	    57	
297	    58	    /** High season: from December 15 to the end of February, and the whole of July. */
298	    59	    static boolean isHighSeason(LocalDate date) {
299	    60	        Month month = date.getMonth();
300	    61	        return month == Month.JANUARY
301	    62	                || month == Month.FEBRUARY
302	    63	                || month == Month.JULY
303	    64	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
304	    65	    }
305	    66	
306	    67	    static BigDecimal cents(BigDecimal value) {
307	    68	        return value.setScale(2, RoundingMode.HALF_EVEN);
308	    69	    }
309	    70	}
