    79	    /** Whether a reservation that was not cancelled holds the room on any of the nights. */
    80	    boolean isRoomTaken(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
    81	        try (Connection connection = dataSource.getConnection();
    82	                PreparedStatement select = connection.prepareStatement(
    83	                        "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
    84	                                + "AND check_in < ? AND ? < check_out")) {
    85	            select.setInt(1, roomNumber);
    86	            select.setDate(2, Date.valueOf(checkOut));
    87	            select.setDate(3, Date.valueOf(checkIn));
    88	            try (ResultSet rows = select.executeQuery()) {
    89	                return rows.next();
    90	            }
    91	        } catch (SQLException failure) {
    92	            throw new IllegalStateException("could not check room " + roomNumber, failure);
    93	        }
    94	    }
