    96	    public Optional<Reservation> find(long id) {
    97	        try (Connection connection = dataSource.getConnection();
    98	                PreparedStatement select = connection.prepareStatement(
    99	                        "SELECT " + COLUMNS + " FROM reservations WHERE id = ?")) {
   100	            select.setLong(1, id);
   101	            try (ResultSet rows = select.executeQuery()) {
   102	                return rows.next() ? Optional.of(read(rows)) : Optional.empty();
   103	            }
   104	        } catch (SQLException failure) {
   105	            throw new IllegalStateException("could not read reservation " + id, failure);
   106	        }
   107	    }
   108	
   109	    public List<Reservation> all() {
   110	        try (Connection connection = dataSource.getConnection();
   111	                PreparedStatement select = connection.prepareStatement(
   112	                        "SELECT " + COLUMNS + " FROM reservations ORDER BY id");
   113	                ResultSet rows = select.executeQuery()) {
   114	            List<Reservation> reservations = new ArrayList<>();
   115	            while (rows.next()) {
