186	        Reservation pending = service.create(stay(101, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD));
187	        Reservation standard = service.create(stay(102, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD));
188	        Reservation nonRefundable = service.create(stay(201, "2027-03-10", "2027-03-11", 1, RatePlan.NON_REFUNDABLE));
189	        service.confirm(standard.id());
190	        service.confirm(nonRefundable.id());
191	
192	        assertEquals(new BigDecimal("0.00"), service.cancel(pending.id()).refund());
193	        assertEquals(new BigDecimal("249.90"), service.cancel(standard.id()).refund());
