246	/**
247	 * The database the tests use, in the same variables as the service (DB_URL, DB_USER, DB_PASSWORD), emptied when
248	 * opened: no reservation, no message, and the numbering back to 1. The rooms stay.
249	 */
250	public final class EmptyDatabase implements AutoCloseable {
251	
252	    private final Database database = new Database(System.getenv());
253	
254	    public EmptyDatabase() {
255	        try (Connection connection = database.dataSource().getConnection();
256	                Statement statement = connection.createStatement()) {
257	            statement.execute("TRUNCATE reservations, messages RESTART IDENTITY CASCADE");
258	        } catch (SQLException failure) {
259	            throw new IllegalStateException("could not empty the test database", failure);
260	        }
261	    }
262	
263	    public DataSource dataSource() {
264	        return database.dataSource();
265	    }
266	
267	    @Override
268	    public void close() {
269	        database.close();
270	    }
271	}

